package com.pointverse.app;
import android.test.InstrumentationTestCase;import android.graphics.*;import android.view.*;import android.widget.FrameLayout;import java.util.*;import java.util.concurrent.*;
@SuppressWarnings("deprecation")
public final class UniverseGestureTest extends InstrumentationTestCase {
 UniverseCanvas canvas;List<String> opened=new ArrayList<>();float d;
 <T>T ui(Callable<T> action)throws Exception{FutureTask<T> task=new FutureTask<>(action);getInstrumentation().runOnMainSync(task);return task.get();}
 protected void setUp()throws Exception {super.setUp();ui(()->{d=getInstrumentation().getTargetContext().getResources().getDisplayMetrics().density;canvas=new UniverseCanvas(getInstrumentation().getTargetContext(),Arrays.asList(UniverseSceneTest.point("a","领域","主题"),UniverseSceneTest.point("b","领域","主题")),new SemanticIndex(getInstrumentation().getTargetContext()),false,opened::add);FrameLayout parent=new FrameLayout(getInstrumentation().getTargetContext());parent.addView(canvas);canvas.layout(0,0,(int)(360*d),(int)(600*d));return null;});}
 protected void tearDown()throws Exception {ui(()->{canvas.onDetachedFromWindow();return null;});super.tearDown();}
 void event(int action,float x,float y,long down,long time){MotionEvent e=MotionEvent.obtain(down,time,action,x*d,y*d,0);canvas.onTouchEvent(e);e.recycle();}
 void tap(float x,float y){long t=android.os.SystemClock.uptimeMillis();event(0,x,y,t,t);event(1,x,y,t,t+40);}
 UniverseScene.Planet fit() {UniverseScene.Planet p=canvas.scene.planets.get(0);double[] target=canvas.scene.destination(p,220,360,600);canvas.state.cameraX=target[0];canvas.state.cameraY=target[1];canvas.state.distance=target[2];canvas.state.target=p.id;return p;}
 void draw(){Bitmap b=Bitmap.createBitmap(canvas.getWidth(),canvas.getHeight(),Bitmap.Config.ARGB_8888);canvas.draw(new Canvas(b));b.recycle();}
 public void testPlanetFirstTapApproachesWithoutOpeningIdea()throws Exception {ui(()->{UniverseScene.Planet p=canvas.scene.planets.get(0);canvas.state.target="";UniverseScene.Projection v=canvas.scene.project(p,360,600);tap((float)v.x,(float)v.y);assertEquals(p.id,canvas.state.target);assertEquals(0,opened.size());return null;});}
 public void testBackdropDragPansWithoutOpening()throws Exception {ui(()->{double x=canvas.state.cameraX;long t=android.os.SystemClock.uptimeMillis();event(0,2,590,t,t);event(2,62,590,t,t+30);event(1,62,590,t,t+60);assertTrue(Math.abs(x-canvas.state.cameraX)>.01);assertEquals(0,opened.size());return null;});}
 public void testSurfaceDragRotatesInsteadOfPanning()throws Exception {ui(()->{UniverseScene.Planet p=fit();double x=canvas.state.cameraX;long t=android.os.SystemClock.uptimeMillis();event(0,180,300,t,t);event(2,220,320,t,t+30);event(1,220,320,t,t+60);assertEquals(x,canvas.state.cameraX,0);assertFalse(Arrays.equals(new UniverseScene.Rotation().m,canvas.scene.rotation(p).m));assertEquals(0,opened.size());return null;});}
 public void testClusterDoesNotOpenArbitraryMember()throws Exception {ui(()->{UniverseScene.Planet p=fit();p.nodes.clear();p.nodes.add(new UniverseScene.Node(UniverseSceneTest.point("a","领域","主题"),"主题",new UniverseScene.V(0,0,1)));p.nodes.add(new UniverseScene.Node(UniverseSceneTest.point("b","领域","主题"),"主题",new UniverseScene.V(0,0,1)));draw();tap(180,300);assertEquals(0,opened.size());return null;});}
 public void testFrontLeafOpensButBackLeafDoesNot()throws Exception {ui(()->{UniverseScene.Planet p=fit();p.nodes.clear();PointStore.Point point=UniverseSceneTest.point("a","领域","主题");p.nodes.add(new UniverseScene.Node(point,"主题",new UniverseScene.V(0,0,-1)));draw();tap(180,300);assertEquals(0,opened.size());p.nodes.clear();p.nodes.add(new UniverseScene.Node(point,"主题",new UniverseScene.V(0,0,1)));draw();tap(180,300);assertEquals(Arrays.asList("a"),opened);return null;});}
 public void testSearchOrientsPointAndSharedStateSurvivesViewReplacement()throws Exception {ui(()->{canvas.focus("a");UniverseScene.Planet p=canvas.scene.owner.get("a");UniverseScene.V v=canvas.scene.rotation(p).apply(canvas.scene.nodes.get("a").unit);assertTrue(v.z>.999);canvas.state.cameraX=3.14;UniverseCanvas restored=new UniverseCanvas(getInstrumentation().getTargetContext(),Arrays.asList(UniverseSceneTest.point("a","领域","主题")),new SemanticIndex(getInstrumentation().getTargetContext()),false,canvas.state,opened::add);assertEquals(3.14,restored.state.cameraX,0);assertEquals("a",restored.state.focused);restored.onDetachedFromWindow();return null;});}
 void pointers(int action,long t,long now,float span){MotionEvent.PointerProperties[] pp={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] pc={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){pp[i].id=i;pp[i].toolType=MotionEvent.TOOL_TYPE_FINGER;pc[i].x=(180+(i==0?-span:span)/2)*d;pc[i].y=300*d;pc[i].pressure=1;pc[i].size=1;}MotionEvent e=MotionEvent.obtain(t,now,action,2,pp,pc,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);canvas.onTouchEvent(e);e.recycle();}
 public void testPinchAndRemainingFingerDoNotOpenPoint()throws Exception {ui(()->{UniverseScene.Planet p=fit();draw();double before=canvas.scene.project(p,360,600).r;long t=android.os.SystemClock.uptimeMillis();event(0,130,300,t,t);pointers(MotionEvent.ACTION_POINTER_DOWN|(1<<8),t,t+20,100);pointers(MotionEvent.ACTION_MOVE,t,t+80,140);pointers(MotionEvent.ACTION_MOVE,t,t+160,180);pointers(MotionEvent.ACTION_POINTER_UP|(1<<8),t,t+200,180);event(1,90,300,t,t+220);assertEquals(0,opened.size());assertTrue("before="+before+" after="+canvas.scene.project(p,360,600).r,canvas.scene.project(p,360,600).r>before);return null;});}

 public void testStarCoreIsBrightRatherThanInheritingOrbitTransparency()throws Exception {ui(()->{UniverseScene.V star=canvas.scene.system(0);canvas.state.cameraX=star.x;canvas.state.cameraY=star.y;canvas.state.distance=star.z+20;Bitmap image=Bitmap.createBitmap(canvas.getWidth(),canvas.getHeight(),Bitmap.Config.ARGB_8888);canvas.draw(new Canvas(image));int color=image.getPixel(image.getWidth()/2,image.getHeight()/2);image.recycle();assertTrue("恒星亮核应明显亮于背景",Color.red(color)>200&&Color.green(color)>160);return null;});}

}
